def seed_consent_texts(apps, schema_editor):
    ConsentTextVersion = apps.get_model("identity", "ConsentTextVersion")
    texts = {
        "it": "Autorizzo la condivisione dei dati clinici indicati con il destinatario, per la finalità specificata, fino alla scadenza o alla revoca. Posso revocare il consenso in qualsiasi momento.",
        "en": "I authorize sharing the specified health data with the recipient for the stated purpose until expiration or withdrawal. I may withdraw consent at any time.",
    }
    for locale, text in texts.items():
        ConsentTextVersion.objects.get_or_create(
            purpose="care_sharing",
            version=1,
            locale=locale,
            defaults={"text": text, "content_hash": hashlib.sha256(text.encode()).hexdigest()},
        )


